//! A real `stream` Operation handler and generated-content download.
//!
//! `Ingest` reads the caller's live bytes as they arrive; its input value
//! selects the behaviour (`complete`, `fail-after-partial`, `await-error`).
//! `Generate` serves `size` generated bytes from a provider reader whose size
//! and digest are declared up front; `lie` declares a wrong digest.

use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use runtime_trellis::apis::runtime_trellis_runtime_v1::rpc::GenerateOutput;
use runtime_trellis::participants::runtime_trellis_operation_provider::{Participant, Provider};
use runtime_trellis::types::Value;
use serde_json::json;
use sha2::{Digest as _, Sha256};
use std::io::Write as _;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, BufReader};
use trellis_rs::service::{generate_transfer_id, FileTransferInfo, ServerError};

fn emit(value: serde_json::Value) {
    println!("{value}");
    std::io::stdout().flush().unwrap();
}

fn pattern(size: usize) -> Vec<u8> {
    (0..size).map(|index| (index % 251) as u8).collect()
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut service = Participant::connect(
        trellis_runtime_acceptance::service_options(
            &std::env::var("TRELLIS_URL")?,
            &std::env::var("TRELLIS_IDENTITY_SEED")?,
        )
        .await?,
    )
    .await?;
    let mut provider = Provider::new(&mut service);
    provider
        .runtime_trellis_runtime_v1()
        .register_ingest(|_, input, operation| async move {
            let mut stream = operation
                .take_upload_stream()
                .ok_or_else(|| ServerError::Nats("stream upload missing".into()))?;
            assert!(operation.take_upload_stream().is_none(), "taken once");
            let mut hasher = Sha256::new();
            let mut size = 0usize;
            let mut buffer = vec![0; 64 * 1024];
            let mut announced = false;
            loop {
                let read = match stream.read(&mut buffer).await {
                    Ok(read) => read,
                    Err(error) => {
                        emit(json!({"streamError": error.to_string()}));
                        return Err(ServerError::Nats(error.to_string()));
                    }
                };
                if read == 0 {
                    break;
                }
                hasher.update(&buffer[..read]);
                size += read;
                if !announced {
                    announced = true;
                    // The caller is still sending: bytes reach the handler
                    // before the upload completes.
                    emit(json!({"partial": size}));
                    if input.value == "fail-after-partial" {
                        return Err(ServerError::Nats("handler rejected the stream".into()));
                    }
                }
            }
            let info = operation
                .upload()
                .await?
                .ok_or_else(|| ServerError::Nats("verified stream metadata missing".into()))?;
            let digest = format!("SHA-256={}", URL_SAFE_NO_PAD.encode(hasher.finalize()));
            assert_eq!(info.size, size as u64);
            assert_eq!(info.digest.trim_end_matches('='), digest);
            emit(json!({"streamed": size}));
            operation
                .complete(Value {
                    value: format!("rust:{size}:{digest}"),
                    extra: Default::default(),
                })
                .await?;
            Ok(())
        });
    provider
        .runtime_trellis_runtime_v1()
        .register_generate(|context, input| async move {
            let lie = input.value == "lie";
            let size = if lie {
                4096
            } else {
                input.value.parse::<usize>().unwrap_or(0)
            };
            let bytes = pattern(size);
            // `lie` declares the digest of different bytes of the same size.
            let declared = if lie {
                Sha256::digest(vec![0u8; size])
            } else {
                Sha256::digest(&bytes)
            };
            let digest = format!("SHA-256={}", URL_SAFE_NO_PAD.encode(declared));
            let now = time::OffsetDateTime::now_utc();
            let format = &time::format_description::well_known::Rfc3339;
            let plan = context.plan_stream_download_transfer(
                &generate_transfer_id().map_err(|error| ServerError::Nats(error.to_string()))?,
                &(now + time::Duration::minutes(2))
                    .format(format)
                    .expect("timestamp"),
                FileTransferInfo {
                    key: "generated".into(),
                    size: size as u64,
                    updated_at: now.format(format).expect("timestamp"),
                    digest,
                    content_type: Some("application/octet-stream".into()),
                    metadata: Default::default(),
                },
            )?;
            let grant = plan.grant.clone();
            context
                .handle()
                .spawn_stream_download_endpoint(plan, std::io::Cursor::new(bytes))
                .await?;
            Ok(GenerateOutput {
                response: input,
                transfer: Some(grant.into()),
            })
        });
    emit(json!({"ready": "provider"}));
    let stop = async {
        let mut lines = BufReader::new(tokio::io::stdin()).lines();
        assert_eq!(lines.next_line().await.unwrap().as_deref(), Some("stop"));
    };
    tokio::select! { result = service.run() => result?, () = stop => {} }
    Ok(())
}
